#include "log.h"

#include <fcntl.h>
#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

/* /dev/kmsg priority prefixes */
#define KM_INFO  "<6>"
#define KM_WARN  "<4>"
#define KM_ERR   "<3>"

static int kmsg_fd = -1;

void log_init(void) {
    kmsg_fd = open("/dev/kmsg", O_WRONLY | O_CLOEXEC);
}

static void log_write(const char *level, const char *fmt, va_list ap) {
    char buf[512];
    char msg[480];

    vsnprintf(msg, sizeof(msg), fmt, ap);
    snprintf(buf, sizeof(buf), "%sminit: %s\n", level, msg);

    if (kmsg_fd >= 0)
        write(kmsg_fd, buf, strlen(buf));
    else
        write(STDERR_FILENO, buf, strlen(buf));
}

void log_info(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    log_write(KM_INFO, fmt, ap);
    va_end(ap);
}

void log_warn(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    log_write(KM_WARN, fmt, ap);
    va_end(ap);
}

void log_error(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    log_write(KM_ERR, fmt, ap);
    va_end(ap);
}

