#include "socket.h"
#include "minit.h"
#include "log.h"

#include <sys/socket.h>
#include <sys/un.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/*
 * Simple line protocol over Unix socket:
 *
 *   LAUNCH <path>        -> "OK <pid>\n"  or  "ERR\n"
 *   KILL <pid>           -> "OK\n"        or  "ERR\n"
 *   STATUS               -> "SHELL <pid> PROCS <n>\n"
 */

int init_socket(const char *path) {
    struct sockaddr_un addr;
    int fd;

    unlink(path);

    fd = socket(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
    if (fd < 0) {
        log_error("socket: failed to create");
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, path, sizeof(addr.sun_path) - 1);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_error("socket: bind failed on %s", path);
        return -1;
    }

    listen(fd, 8);
    log_info("socket: listening on %s", path);
    return fd;
}

static void handle_command(int client_fd) {
    char buf[512];
