#include <sys/select.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>

extern char **environ;

pid_t       shell_pid = -1;
proc_entry_t proc_table[MAX_PROCS];

static int sigchld_pipe[2];

/* ------------------------------------------------------------------ */
/* Signal handlers                                                      */
/* ------------------------------------------------------------------ */

static void sigchld_handler(int sig) {
    (void)sig;
    /* wake up select() — actual reaping happens in main loop */
    write(sigchld_pipe[1], "\0", 1);
}

static void panic_handler(int sig) {
    log_error("panic: caught signal %d — force killing all processes", sig);

    /* kill every process except PID 1 (us) */
    kill(-1, SIGKILL);

    /* mark all proc_table entries dead */
    memset(proc_table, 0, sizeof(proc_table));

    log_warn("panic: respawning shell");
    shell_pid = launch(SHELL_PATH, NULL);
}

/* ------------------------------------------------------------------ */
/* Filesystem setup                                                     */
/* ------------------------------------------------------------------ */

void mount_essential_fs(void) {
    mkdir("/dev", 0755);
    mkdir("/sys", 0755);
    mkdir("/run", 0755);
    mkdir("/var", 0755);
    mkdir("/var/log", 0755);

    mount("devtmpfs", "/dev", "devtmpfs", MS_NOSUID,       "mode=0755");
    mount("sysfs",    "/sys", "sysfs",    MS_NOSUID | MS_NODEV | MS_NOEXEC, NULL);
    mount("tmpfs",    "/run", "tmpfs",    MS_NOSUID | MS_NODEV, "mode=0755");
}

/* ------------------------------------------------------------------ */
/* Process launching                                                    */
/* ------------------------------------------------------------------ */

static int proc_table_add(pid_t pid, const char *path) {
    for (int i = 0; i < MAX_PROCS; i++) {
        if (!proc_table[i].active) {
            proc_table[i].pid    = pid;
            proc_table[i].active = 1;
            proc_table[i].retries = 0;
            strncpy(proc_table[i].path, path, sizeof(proc_table[i].path) - 1);
            return i;
        }
    }
    return -1;
}

static void proc_table_remove(pid_t pid) {
    for (int i = 0; i < MAX_PROCS; i++) {
        if (proc_table[i].active && proc_table[i].pid == pid) {
            proc_table[i].active = 0;
            return;
        }
    }
}

pid_t launch(const char *path, char *const argv[]) {
    pid_t pid = fork();
    if (pid < 0) {
        log_error("fork failed for %s", path);
        return -1;
    }

    if (pid == 0) {
        /* child */
        char *default_argv[] = { (char *)path, NULL };
        execve(path, argv ? argv : default_argv, environ);
        /* execve only returns on failure */
        _exit(127);
    }

    /* parent */
    proc_table_add(pid, path);
    log_info("launched %s as pid %d", path, pid);
    return pid;
}

pid_t launch_with_retry(const char *path, char *const argv[]) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        pid_t pid = fork();
        if (pid < 0) {
            log_warn("fork attempt %d/%d failed for %s", i + 1, MAX_RETRIES, path);
            continue;
        }

        if (pid == 0) {
            char *default_argv[] = { (char *)path, NULL };
            execve(path, argv ? argv : default_argv, environ);
            _exit(127);
        }

        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            proc_table_add(pid, path);
            log_info("launched %s as pid %d (attempt %d)", path, pid, i + 1);
            return pid;
        }

        log_warn("attempt %d/%d: %s exited with status %d",
                 i + 1, MAX_RETRIES, path, WEXITSTATUS(status));
    }

    log_error("all %d attempts failed for %s — returning to shell", MAX_RETRIES, path);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Child reaping                                                        */
/* ------------------------------------------------------------------ */

static void reap_children(void) {
    int status;
    pid_t pid;

    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        proc_table_remove(pid);
        log_info("pid %d exited (status %d)", pid, WEXITSTATUS(status));

        if (pid == shell_pid) {
            log_warn("shell (pid %d) died — respawning", pid);
            shell_pid = launch(SHELL_PATH, NULL);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void) {
    memset(proc_table, 0, sizeof(proc_table));

    log_init();
    log_info("minit starting");

    mount_essential_fs();

    /* self-pipe for SIGCHLD */
    pipe(sigchld_pipe);
    fcntl(sigchld_pipe[0], F_SETFL, O_NONBLOCK);
    fcntl(sigchld_pipe[1], F_SETFL, O_NONBLOCK | O_CLOEXEC);

    /* signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_flags   = SA_RESTART;
    sa.sa_handler = sigchld_handler;
    sigaction(SIGCHLD, &sa, NULL);

    sa.sa_handler = panic_handler;
    sigaction(SIGSEGV, &sa, NULL);
    sigaction(SIGABRT, &sa, NULL);
    sigaction(SIGBUS,  &sa, NULL);

    /* ignore SIGTERM sent to the whole session — we handle shutdown */
    sa.sa_handler = SIG_IGN;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGHUP,  &sa, NULL);

    /* launch socket API */
    int sock_fd = init_socket(MINIT_SOCKET_PATH);

    /* launch shell as first process */
    shell_pid = launch(SHELL_PATH, NULL);
    log_info("shell started as pid %d", shell_pid);

    /* main event loop */
    while (1) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(sigchld_pipe[0], &rfds);
        if (sock_fd >= 0)
            FD_SET(sock_fd, &rfds);

        int nfds = sock_fd > sigchld_pipe[0] ? sock_fd + 1 : sigchld_pipe[0] + 1;
        select(nfds, &rfds, NULL, NULL, NULL);

        if (FD_ISSET(sigchld_pipe[0], &rfds)) {
            char drain[64];
            read(sigchld_pipe[0], drain, sizeof(drain));
            reap_children();
        }

        if (sock_fd >= 0 && FD_ISSET(sock_fd, &rfds))
            handle_socket_client(sock_fd);
    }

    return 0; /* never reached — PID 1 must never exit */
}

