#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <stdlib.h>
#include <sys/utsname.h>
#include <sys/sysinfo.h>

/* ------------------------------------------------------------------ */
/* ANSI colors                                                          */
/* ------------------------------------------------------------------ */

#define R       "\033[0m"
#define BOLD    "\033[1m"
#define WHITE   "\033[1;37m"
#define YELLOW  "\033[1;33m"
#define CYAN    "\033[1;36m"
#define BLUE    "\033[1;34m"
#define BLACK   "\033[0;30m"
#define DKGRAY  "\033[90m"

/* ------------------------------------------------------------------ */
/* Tux                                                                  */
/* ------------------------------------------------------------------ */

/*
 * Each line is exactly 20 visible characters wide (padded with spaces)
 * so info columns align cleanly regardless of ANSI escape length.
 *
 * Colors:
 *   body outline  — WHITE
 *   eyes          — YELLOW on WHITE face
 *   beak / feet   — YELLOW
 *   belly         — WHITE (same, readable on dark terminals)
 */
static const char *tux[] = {
/*0*/  "      " WHITE  ".--." R "              ",
/*1*/  "     " WHITE   "|" YELLOW "o" WHITE "_" YELLOW "o" WHITE " |" R "           ",
/*2*/  "     " WHITE   "|" YELLOW ":_/" WHITE " |" R "           ",
/*3*/  "    " WHITE    "//   \\ \\" R "          ",
/*4*/  "   " WHITE     "(|     | )" R "         ",
/*5*/  "  " WHITE      "/'\\_ " R "  " WHITE "_/`\\" R "        ",
/*6*/  "  " WHITE      "\\___)=" YELLOW "(" WHITE "___/" R "        ",
/*7*/  "                              ",
};

#define TUX_LINES  8

/* ------------------------------------------------------------------ */
/* CPU brand string (x86 / x86_64 only via CPUID)                     */
/* ------------------------------------------------------------------ */

#if defined(__x86_64__) || defined(__i386__)
static void cpu_brand(char out[49]) {
    unsigned int *p = (unsigned int *)(void *)out;
    unsigned int leaf;
    for (leaf = 0x80000002; leaf <= 0x80000004; leaf++, p += 4) {
        __asm__ volatile (
            "cpuid"
            : "=a"(p[0]), "=b"(p[1]), "=c"(p[2]), "=d"(p[3])
            : "a"(leaf)
        );
    }
    out[48] = '\0';
    /* trim leading spaces */
    char *s = out;
    while (*s == ' ') s++;
    if (s != out) memmove(out, s, strlen(s) + 1);
}
#else
static void cpu_brand(char out[49]) {
    strncpy(out, "unknown arch", 49);
}
#endif

/* ------------------------------------------------------------------ */
/* Helpers                                                              */
/* ------------------------------------------------------------------ */

static void fmt_uptime(long seconds, char *buf, size_t len) {
    long d = seconds / 86400;
    long h = (seconds % 86400) / 3600;
    long m = (seconds % 3600)  / 60;
    long s = seconds % 60;

    if (d > 0)
        snprintf(buf, len, "%ldd %ldh %ldm", d, h, m);
    else if (h > 0)
        snprintf(buf, len, "%ldh %ldm", h, m);
    else if (m > 0)
        snprintf(buf, len, "%ldm %lds", m, s);
    else
        snprintf(buf, len, "%lds", s);
}

static void fmt_mem(unsigned long bytes, char *buf, size_t len) {
    if (bytes >= 1024UL * 1024 * 1024)
        snprintf(buf, len, "%.1f GB", bytes / (1024.0 * 1024 * 1024));
    else if (bytes >= 1024UL * 1024)
        snprintf(buf, len, "%.0f MB", bytes / (1024.0 * 1024));
    else
        snprintf(buf, len, "%.0f KB", bytes / 1024.0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void) {
    struct utsname   uts;
    struct sysinfo   si;
    char hostname[256];
    char uptime_str[32];
    char mem_used[32], mem_total[32];
    char cpu[49];
    char load[64];

    uname(&uts);
    sysinfo(&si);
    gethostname(hostname, sizeof(hostname));
    cpu_brand(cpu);

    unsigned long unit    = si.mem_unit;
    unsigned long total_b = si.totalram  * unit;
    unsigned long free_b  = si.freeram   * unit;
    unsigned long used_b  = total_b - free_b;

    fmt_uptime(si.uptime, uptime_str, sizeof(uptime_str));
    fmt_mem(used_b,  mem_used,  sizeof(mem_used));
    fmt_mem(total_b, mem_total, sizeof(mem_total));

    /* load averages — kernel scales by 1<<16 */
    snprintf(load, sizeof(load), "%.2f  %.2f  %.2f",
             si.loads[0] / 65536.0,
             si.loads[1] / 65536.0,
             si.loads[2] / 65536.0);

    const char *shell = getenv("SHELL");
    if (!shell) shell = "/bin/sh";

    /* build info lines — label + value pairs */
    #define LABEL(l)  BLUE BOLD l R
    #define VAL(v)    WHITE v R

    char info_hostname[512];
    char info_sep[512];
    char info_os[512];
    char info_kernel[512];
    char info_uptime[512];
    char info_cpu[512];
    char info_mem[512];
    char info_load[512];
    char info_shell[512];
    char info_procs[512];

    snprintf(info_hostname, sizeof(info_hostname),
             CYAN BOLD "%s" R "@" CYAN BOLD "%s" R, uts.nodename, hostname);

    /* separator length matches visible hostname length */
    {
        int seplen = (int)(strlen(uts.nodename) + 1 + strlen(hostname));
        char sep[128];
        for (int i = 0; i < seplen && i < 127; i++) sep[i] = '-';
        sep[seplen < 127 ? seplen : 127] = '\0';
        snprintf(info_sep, sizeof(info_sep), WHITE "%s" R, sep);
    }

    snprintf(info_os,     sizeof(info_os),
             LABEL("OS:      ") VAL("Linux %s"), uts.release);
    snprintf(info_kernel, sizeof(info_kernel),
             LABEL("Kernel:  ") VAL("%s"), uts.version);
    snprintf(info_uptime, sizeof(info_uptime),
             LABEL("Uptime:  ") VAL("%s"), uptime_str);
    snprintf(info_cpu,    sizeof(info_cpu),
             LABEL("CPU:     ") VAL("%s"), cpu);
    snprintf(info_mem,    sizeof(info_mem),
             LABEL("Memory:  ") VAL("%s / %s"), mem_used, mem_total);
    snprintf(info_load,   sizeof(info_load),
             LABEL("Load:    ") VAL("%s") DKGRAY " (1m 5m 15m)" R, load);
    snprintf(info_shell,  sizeof(info_shell),
             LABEL("Shell:   ") VAL("%s"), shell);
    snprintf(info_procs,  sizeof(info_procs),
             LABEL("Procs:   ") VAL("%d"), si.procs);

    const char *info[] = {
        info_hostname,
        info_sep,
        info_os,
        info_kernel,
