#include "socket.h"
#include "minit.h"
#include "log.h"

#include <sys/socket.h>
#include <sys/un.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/*
 * Simple line protocol over Unix socket:
 *
 *   LAUNCH <path>        -> "OK <pid>\n"  or  "ERR\n"
 *   KILL <pid>           -> "OK\n"        or  "ERR\n"
 *   STATUS               -> "SHELL <pid> PROCS <n>\n"
 */

int init_socket(const char *path) {
    struct sockaddr_un addr;
    int fd;

    unlink(path);

    fd = socket(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
    if (fd < 0) {
        log_error("socket: failed to create");
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, path, sizeof(addr.sun_path) - 1);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_error("socket: bind failed on %s", path);
        return -1;
    }

    listen(fd, 8);
    log_info("socket: listening on %s", path);
    return fd;
}

static void handle_command(int client_fd) {
    char buf[512];
    ssize_t n;
    char resp[64];

    n = read(client_fd, buf, sizeof(buf) - 1);
    if (n <= 0)
        return;
    buf[n] = '\0';

    /* strip trailing newline */
    buf[strcspn(buf, "\n")] = '\0';

    if (strncmp(buf, "LAUNCH ", 7) == 0) {
        const char *path = buf + 7;
        pid_t pid = launch_with_retry(path, NULL);
        if (pid > 0)
            snprintf(resp, sizeof(resp), "OK %d\n", pid);
        else
            snprintf(resp, sizeof(resp), "ERR\n");

    } else if (strncmp(buf, "KILL ", 5) == 0) {
        pid_t pid = (pid_t)atoi(buf + 5);
        if (pid > 1 && kill(pid, SIGTERM) == 0)
            snprintf(resp, sizeof(resp), "OK\n");
        else
            snprintf(resp, sizeof(resp), "ERR\n");

    } else if (strcmp(buf, "STATUS") == 0) {
        int active = 0;
        for (int i = 0; i < MAX_PROCS; i++)
            if (proc_table[i].active) active++;
        snprintf(resp, sizeof(resp), "SHELL %d PROCS %d\n", shell_pid, active);

    } else {
        snprintf(resp, sizeof(resp), "ERR unknown command\n");
    }

    write(client_fd, resp, strlen(resp));
}

void handle_socket_client(int sock_fd) {
    int client_fd = accept(sock_fd, NULL, NULL);
    if (client_fd < 0)
        return;

    handle_command(client_fd);
    close(client_fd);
}

