#include "minit.h"
#include "log.h"
#include "socket.h"

#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mount.h>
#include <sys/select.h>
#include <sys/signalfd.h>
#include <sys/stat.h>
#include <sys/sysinfo.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <termios.h>
#include <unistd.h>

/* ------------------------------------------------------------------ */
/* Globals                                                              */
/* ------------------------------------------------------------------ */

pid_t        shell_pid = -1;
proc_entry_t proc_table[MAX_PROCS];

char *init_env[] = {
    "PATH=/bin:/sbin",
    "HOME=/root",
    "TERM=linux",
    "SHELL=" SHELL_PATH,
    NULL
};

static int sig_fd  = -1;
static int sock_fd = -1;

/* ------------------------------------------------------------------ */
/* Filesystem                                                           */
/* ------------------------------------------------------------------ */

void mount_essential_fs(void) {
    mkdir("/dev",     0755);
    mkdir("/sys",     0755);
    mkdir("/run",     0755);
    mkdir("/root",    0700);
    mkdir("/var",     0755);
    mkdir("/var/log", 0755);

    mount("devtmpfs", "/dev", "devtmpfs", MS_NOSUID, "mode=0755");
    mount("sysfs",    "/sys", "sysfs",    MS_NOSUID | MS_NODEV | MS_NOEXEC, NULL);
    mount("tmpfs",    "/run", "tmpfs",    MS_NOSUID | MS_NODEV, "mode=0755");
}

/* ------------------------------------------------------------------ */
/* Process table                                                        */
/* ------------------------------------------------------------------ */

void proc_table_add(pid_t pid, const char *path, int is_shell) {
    for (int i = 0; i < MAX_PROCS; i++) {
        if (!proc_table[i].active) {
            proc_table[i].pid      = pid;
            proc_table[i].retries  = 0;
            proc_table[i].active   = 1;
            proc_table[i].is_shell = is_shell;
            strncpy(proc_table[i].path, path, sizeof(proc_table[i].path) - 1);
            return;
        }
    }
    log_warn("proc_table full, cannot track pid %d", pid);
}

void proc_table_remove(pid_t pid) {
    for (int i = 0; i < MAX_PROCS; i++) {
        if (proc_table[i].active && proc_table[i].pid == pid) {
            proc_table[i].active = 0;
            return;
        }
    }
}

proc_entry_t *proc_table_find(pid_t pid) {
    for (int i = 0; i < MAX_PROCS; i++)
        if (proc_table[i].active && proc_table[i].pid == pid)
            return &proc_table[i];
    return NULL;
}

/* ------------------------------------------------------------------ */
/* Fork / exec                                                          */
/* ------------------------------------------------------------------ */

pid_t do_fork_exec(const char *path, char *const argv[], int give_tty) {
    pid_t pid = fork();
    if (pid < 0) {
        log_error("fork failed for %s", path);
        return -1;
    }

    if (pid == 0) {
        /* child: clear blocked signal mask inherited from PID 1 */
        sigset_t empty;
        sigemptyset(&empty);
        sigprocmask(SIG_SETMASK, &empty, NULL);

        /* close signalfd and socket — they have O_CLOEXEC but be explicit */
        if (sig_fd  >= 0) close(sig_fd);
        if (sock_fd >= 0) close(sock_fd);

        if (give_tty) {
            /* new session so we can acquire a controlling terminal */
            setsid();
            int tty = open("/dev/console", O_RDWR | O_NOCTTY);
            if (tty >= 0) {
                ioctl(tty, TIOCSCTTY, 1);
                dup2(tty, STDIN_FILENO);
                dup2(tty, STDOUT_FILENO);
                dup2(tty, STDERR_FILENO);
                if (tty > STDERR_FILENO) close(tty);
            }
        }

        char *default_argv[] = { (char *)path, NULL };
        execve(path, argv ? argv : default_argv, init_env);
        /* execve only returns on failure */
        write(STDERR_FILENO, "execve failed\n", 14);
        _exit(127);
    }

    return pid;
}

/* ------------------------------------------------------------------ */
/* Child reaping — called from the main event loop on SIGCHLD          */
/* ------------------------------------------------------------------ */

void reap_children(void) {
    int status;
    pid_t pid;

    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        proc_entry_t *entry = proc_table_find(pid);
        if (!entry) continue;

        int exit_code = WIFEXITED(status) ? WEXITSTATUS(status) : -1;
        int by_signal = WIFSIGNALED(status);

        if (entry->is_shell) {
            /* shell must always come back */
            log_warn("shell (pid %d) died (exit=%d sig=%d) — restarting",
                     pid, exit_code, by_signal ? WTERMSIG(status) : 0);
            char *sh_argv[] = { SHELL_PATH, "-l", NULL };
            pid_t new_pid = do_fork_exec(SHELL_PATH, sh_argv, 1);
            entry->pid     = new_pid;
            entry->retries = 0;

        } else if (exit_code == 0) {
            /* clean exit — done */
            log_info("%s (pid %d) exited cleanly", entry->path, pid);
            entry->active = 0;

        } else if (entry->retries < MAX_RETRIES) {
            entry->retries++;
            log_warn("%s (pid %d) died — retry %d/%d",
                     entry->path, pid, entry->retries, MAX_RETRIES);
            pid_t new_pid = do_fork_exec(entry->path, NULL, 0);
            entry->pid    = new_pid;

        } else {
            log_error("%s exhausted %d retries — giving up", entry->path, MAX_RETRIES);
            entry->active = 0;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Panic — force-kill everything, return to shell                       */
/* ------------------------------------------------------------------ */

static void handle_panic(int signo) {
    log_error("panic: received signal %d — force killing all processes", signo);
    kill(-1, SIGKILL);

