/* Filesystem                                                           */
/* ------------------------------------------------------------------ */

void mount_essential_fs(void) {
    mkdir("/dev",     0755);
    mkdir("/sys",     0755);
    mkdir("/run",     0755);
    mkdir("/root",    0700);
    mkdir("/var",     0755);
    mkdir("/var/log", 0755);

