/* ------------------------------------------------------------------ */
/* Fork / exec                                                          */
/* ------------------------------------------------------------------ */

pid_t do_fork_exec(const char *path, char *const argv[], int give_tty) {
    pid_t pid = fork();
    if (pid < 0) {
        log_error("fork failed for %s", path);
        return -1;
    }

    if (pid == 0) {
        /* child: clear blocked signal mask inherited from PID 1 */
        sigset_t empty;
        sigemptyset(&empty);
        sigprocmask(SIG_SETMASK, &empty, NULL);

