#include "socket.h"
#include "minit.h"
#include "log.h"

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>

/*
 * Line protocol (newline-terminated):
 *
 *   LAUNCH <path>    -> "OK <pid>"   | "ERR <reason>"
 *   KILL <pid>       -> "OK"         | "ERR <reason>"
 *   STATUS           -> "SHELL <pid> PROCS <n>"
 */

int init_socket(const char *path) {
    int fd;
    struct sockaddr_un addr;

    unlink(path);

    fd = socket(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
    if (fd < 0) {
        log_error("socket: failed to create unix socket");
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, path, sizeof(addr.sun_path) - 1);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_error("socket: bind failed on %s", path);
        close(fd);
        return -1;
    }

    if (listen(fd, 8) < 0) {
        log_error("socket: listen failed");
        close(fd);
        return -1;
    }

    log_info("socket: listening on %s", path);
    return fd;
}

static void respond(int fd, const char *msg) {
    write(fd, msg,    strlen(msg));
    write(fd, "\n",   1);
}

static void handle_command(int client_fd) {
    char buf[512];
    char resp[128];
    ssize_t n;

    n = read(client_fd, buf, sizeof(buf) - 1);
    if (n <= 0)
        return;
    buf[n] = '\0';
    buf[strcspn(buf, "\r\n")] = '\0';

    if (strncmp(buf, "LAUNCH ", 7) == 0) {
        const char *path = buf + 7;
        if (*path == '\0') {
            respond(client_fd, "ERR missing path");
            return;
        }

        /* fork the process — retries are handled async in reap_children */
        pid_t pid = do_fork_exec(path, NULL, 0);
        if (pid < 0) {
            respond(client_fd, "ERR fork failed");
            return;
        }

        proc_table_add(pid, path, 0);
        log_info("socket: launched %s as pid %d", path, pid);
        snprintf(resp, sizeof(resp), "OK %d", pid);
        respond(client_fd, resp);

    } else if (strncmp(buf, "KILL ", 5) == 0) {
        pid_t pid = (pid_t)atoi(buf + 5);

        /* never allow killing PID 1 (us) or the shell */
        if (pid <= 1) {
            respond(client_fd, "ERR cannot kill pid <= 1");
            return;
        }
        if (pid == shell_pid) {
            respond(client_fd, "ERR cannot kill shell");
            return;
        }

        if (kill(pid, SIGTERM) < 0) {
            snprintf(resp, sizeof(resp), "ERR kill failed: %d", errno);
            respond(client_fd, resp);
            return;
        }

        log_info("socket: sent SIGTERM to pid %d", pid);
        respond(client_fd, "OK");

    } else if (strcmp(buf, "STATUS") == 0) {
        int active = 0;
        for (int i = 0; i < MAX_PROCS; i++)
            if (proc_table[i].active) active++;
        snprintf(resp, sizeof(resp), "SHELL %d PROCS %d", shell_pid, active);
        respond(client_fd, resp);

    } else {
        respond(client_fd, "ERR unknown command");
    }
}

void handle_socket_client(int sock_fd) {
    int client_fd = accept(sock_fd, NULL, NULL);
    if (client_fd < 0)
        return;
    handle_command(client_fd);
    close(client_fd);
}

#include "log.h"

#include <fcntl.h>
#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

/* /dev/kmsg priority prefixes */
#define KM_INFO  "<6>"
#define KM_WARN  "<4>"
#define KM_ERR   "<3>"

static int kmsg_fd = -1;

void log_init(void) {
    kmsg_fd = open("/dev/kmsg", O_WRONLY | O_CLOEXEC);
}

static void log_write(const char *level, const char *fmt, va_list ap) {
    char buf[512];
    char msg[480];

    vsnprintf(msg, sizeof(msg), fmt, ap);
    snprintf(buf, sizeof(buf), "%sminit: %s\n", level, msg);

    if (kmsg_fd >= 0)
        write(kmsg_fd, buf, strlen(buf));
    else
        write(STDERR_FILENO, buf, strlen(buf));
}

void log_info(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    log_write(KM_INFO, fmt, ap);
    va_end(ap);
}

void log_warn(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    log_write(KM_WARN, fmt, ap);
    va_end(ap);
}

void log_error(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    log_write(KM_ERR, fmt, ap);
    va_end(ap);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/sysinfo.h>
#include <sys/utsname.h>

/* ------------------------------------------------------------------ */
/* ANSI codes                                                           */
/* ------------------------------------------------------------------ */
#define R       "\033[0m"
#define BOLD    "\033[1m"
#define WHITE   "\033[1;37m"
#define YELLOW  "\033[1;33m"
#define CYAN    "\033[1;36m"
#define BLUE    "\033[1;34m"
#define DGRAY   "\033[90m"

/* color blocks printed on the blank line at the bottom of the logo */
#define CBLOCKS \
    "\033[40m  \033[41m  \033[42m  \033[43m  " \
    "\033[44m  \033[45m  \033[46m  \033[47m  " R

/* ------------------------------------------------------------------ */
/* Tux logo                                                             */
/*                                                                      */
/* Every line is exactly 16 visible characters.                         */
/* Trailing spaces are part of the literal to keep column alignment     */
/* stable regardless of ANSI escape lengths.                            */
/*                                                                      */
/* Visible layout (. = space):                                          */
/*   .......--.......   line 0  (6 + 4 + 6  = 16)                      */
/*   .....|o_o.|....   line 1  (5 + 6 + 5  = 16)                      */
/*   .....|:_/.|....   line 2  (5 + 6 + 5  = 16)                      */
/*   ....//...\.\.....   line 3  (4 + 8 + 4  = 16)                      */
/*   ...(|.....|.)...   line 4  (3 + 10 + 3 = 16)                      */
/*   ../'\_.._/`\...   line 5  (2 + 11 + 3 = 16)                      */
/*   ..\___)==___/...   line 6  (2 + 11 + 3 = 16)                      */
/*   ████████████████   line 7  color blocks (16 visible)               */
/* ------------------------------------------------------------------ */

#define LOGO_H 8
#define LOGO_W 16   /* visible width — used for column math */

static const char *logo[LOGO_H] = {
    /* 0 — .......--.......  (6 + ".--.": 4 + 6 = 16) */
    "      " WHITE ".--." R "      ",

    /* 1 — .....|o_o.|.....  (5 + "|o_o |": 6 + 5 = 16) */
    "     " WHITE "|" YELLOW "o" WHITE "_" YELLOW "o" WHITE " |" R "     ",

    /* 2 — .....|:_/.|.....  (5 + "|:_/ |": 6 + 5 = 16) */
    "     " WHITE "|" YELLOW ":_/" WHITE " |" R "     ",

    /* 3 — ....//...\.\.....  (4 + "//   \ \": 8 + 4 = 16) */
    "    " WHITE "//   \\ \\" R "    ",

    /* 4 — ...(|.....|.)...  (3 + "(|     | )": 10 + 3 = 16) */
    "   " WHITE "(|     | )" R "   ",

    /* 5 — ../'\_..._/`\...  (2 + "/'\_   _/`\": 11 + 3 = 16) */
    "  " WHITE "/'\\_   _/`\\" R "   ",

    /* 6 — ..\\___)=(___/...  (2 + "\___)=(___/": 11 + 3 = 16) */
    "  " WHITE "\\___)=(" YELLOW "___/" R "   ",

    /* 7 — color palette blocks, 8 x 2 spaces = 16 visible */
    CBLOCKS "        ",
};

/* ------------------------------------------------------------------ */
/* CPU brand via CPUID (x86 / x86_64 only)                            */
/* ------------------------------------------------------------------ */

#if defined(__x86_64__) || defined(__i386__)
static void get_cpu_brand(char out[49]) {
    unsigned int *p = (unsigned int *)(void *)out;
    unsigned int  leaf;
    /* leaves 0x80000002-0x80000004 give a 48-byte brand string */
    for (leaf = 0x80000002; leaf <= 0x80000004; leaf++, p += 4)
        __asm__ volatile("cpuid"
            : "=a"(p[0]), "=b"(p[1]), "=c"(p[2]), "=d"(p[3])
            : "a"(leaf));
    out[48] = '\0';
    /* trim leading spaces that some BIOSes insert */
    char *s = out;
    while (*s == ' ') s++;
    if (s != out) memmove(out, s, strlen(s) + 1);
}
#else
static void get_cpu_brand(char out[49]) {
    strncpy(out, "unknown arch", 49);
}
#endif

/* ------------------------------------------------------------------ */
/* Formatting helpers                                                   */
/* ------------------------------------------------------------------ */

static void fmt_uptime(long secs, char *buf, size_t len) {
    long d = secs / 86400;
    long h = (secs % 86400) / 3600;
    long m = (secs % 3600)  / 60;
    long s =  secs % 60;

    if      (d) snprintf(buf, len, "%ldd %ldh %ldm",   d, h, m);
    else if (h) snprintf(buf, len, "%ldh %ldm",         h, m);
    else if (m) snprintf(buf, len, "%ldm %lds",         m, s);
    else        snprintf(buf, len, "%lds",               s);
}

static void fmt_bytes(unsigned long bytes, char *buf, size_t len) {
    if      (bytes >= 1024UL * 1024 * 1024)
        snprintf(buf, len, "%.1f GB", bytes / (1024.0 * 1024 * 1024));
    else if (bytes >= 1024UL * 1024)
        snprintf(buf, len, "%.0f MB", bytes / (1024.0 * 1024));
    else
        snprintf(buf, len, "%.0f KB", bytes / 1024.0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void) {
    struct utsname uts;
    struct sysinfo si;
    char hostname[256];
    char uptime_buf[32];
    char mem_used[32], mem_total[32];
    char cpu[49];
    char separator[128];

    uname(&uts);
    sysinfo(&si);
    gethostname(hostname, sizeof(hostname) - 1);
    get_cpu_brand(cpu);

    unsigned long unit  = si.mem_unit;
    unsigned long total = si.totalram  * unit;
    unsigned long used  = (si.totalram - si.freeram) * unit;

    fmt_uptime(si.uptime, uptime_buf, sizeof(uptime_buf));
    fmt_bytes(used,  mem_used,  sizeof(mem_used));
    fmt_bytes(total, mem_total, sizeof(mem_total));

    /* separator matches visible length of "nodename@hostname" */
    {
