#define CYAN    "\033[1;36m"
#define BLUE    "\033[1;34m"
#define DGRAY   "\033[90m"

/* color blocks printed on the blank line at the bottom of the logo */
#define CBLOCKS \
    "\033[40m  \033[41m  \033[42m  \033[43m  " \
    "\033[44m  \033[45m  \033[46m  \033[47m  " R

/* ------------------------------------------------------------------ */
/* Tux logo                                                             */
/*                                                                      */
/* Every line is exactly 16 visible characters.                         */
/* Trailing spaces are part of the literal to keep column alignment     */
/* stable regardless of ANSI escape lengths.                            */
/*                                                                      */
/* Visible layout (. = space):                                          */
/*   .......--.......   line 0  (6 + 4 + 6  = 16)                      */
/*   .....|o_o.|....   line 1  (5 + 6 + 5  = 16)                      */
/*   .....|:_/.|....   line 2  (5 + 6 + 5  = 16)                      */
/*   ....//...\.\.....   line 3  (4 + 8 + 4  = 16)                      */
/*   ...(|.....|.)...   line 4  (3 + 10 + 3 = 16)                      */
/*   ../'\_.._/`\...   line 5  (2 + 11 + 3 = 16)                      */
/*   ..\___)==___/...   line 6  (2 + 11 + 3 = 16)                      */
/*   ████████████████   line 7  color blocks (16 visible)               */
/* ------------------------------------------------------------------ */

#define LOGO_H 8
#define LOGO_W 16   /* visible width — used for column math */

static const char *logo[LOGO_H] = {
    /* 0 — .......--.......  (6 + ".--.": 4 + 6 = 16) */
    "      " WHITE ".--." R "      ",

    /* 1 — .....|o_o.|.....  (5 + "|o_o |": 6 + 5 = 16) */
    "     " WHITE "|" YELLOW "o" WHITE "_" YELLOW "o" WHITE " |" R "     ",

    /* 2 — .....|:_/.|.....  (5 + "|:_/ |": 6 + 5 = 16) */
    "     " WHITE "|" YELLOW ":_/" WHITE " |" R "     ",

    /* 3 — ....//...\.\.....  (4 + "//   \ \": 8 + 4 = 16) */
    "    " WHITE "//   \\ \\" R "    ",

    /* 4 — ...(|.....|.)...  (3 + "(|     | )": 10 + 3 = 16) */
    "   " WHITE "(|     | )" R "   ",

    /* 5 — ../'\_..._/`\...  (2 + "/'\_   _/`\": 11 + 3 = 16) */
    "  " WHITE "/'\\_   _/`\\" R "   ",

    /* 6 — ..\\___)=(___/...  (2 + "\___)=(___/": 11 + 3 = 16) */
    "  " WHITE "\\___)=(" YELLOW "___/" R "   ",

    /* 7 — color palette blocks, 8 x 2 spaces = 16 visible */
    CBLOCKS "        ",
};

/* ------------------------------------------------------------------ */
/* CPU brand via CPUID (x86 / x86_64 only)                            */
/* ------------------------------------------------------------------ */

#if defined(__x86_64__) || defined(__i386__)
static void get_cpu_brand(char out[49]) {
    unsigned int *p = (unsigned int *)(void *)out;
    unsigned int  leaf;
    /* leaves 0x80000002-0x80000004 give a 48-byte brand string */
    for (leaf = 0x80000002; leaf <= 0x80000004; leaf++, p += 4)
        __asm__ volatile("cpuid"
            : "=a"(p[0]), "=b"(p[1]), "=c"(p[2]), "=d"(p[3])
            : "a"(leaf));
    out[48] = '\0';
    /* trim leading spaces that some BIOSes insert */
    char *s = out;
    while (*s == ' ') s++;
    if (s != out) memmove(out, s, strlen(s) + 1);
}
#else
static void get_cpu_brand(char out[49]) {
    strncpy(out, "unknown arch", 49);
}
#endif

/* ------------------------------------------------------------------ */
/* Formatting helpers                                                   */
/* ------------------------------------------------------------------ */

static void fmt_uptime(long secs, char *buf, size_t len) {
    long d = secs / 86400;
    long h = (secs % 86400) / 3600;
    long m = (secs % 3600)  / 60;
    long s =  secs % 60;

    if      (d) snprintf(buf, len, "%ldd %ldh %ldm",   d, h, m);
    else if (h) snprintf(buf, len, "%ldh %ldm",         h, m);
    else if (m) snprintf(buf, len, "%ldm %lds",         m, s);
    else        snprintf(buf, len, "%lds",               s);
}

static void fmt_bytes(unsigned long bytes, char *buf, size_t len) {
    if      (bytes >= 1024UL * 1024 * 1024)
        snprintf(buf, len, "%.1f GB", bytes / (1024.0 * 1024 * 1024));
    else if (bytes >= 1024UL * 1024)
        snprintf(buf, len, "%.0f MB", bytes / (1024.0 * 1024));
    else
        snprintf(buf, len, "%.0f KB", bytes / 1024.0);
}

