/*
 * Line protocol (newline-terminated):
 *
 *   LAUNCH <path>    -> "OK <pid>"   | "ERR <reason>"
 *   KILL <pid>       -> "OK"         | "ERR <reason>"
 *   STATUS           -> "SHELL <pid> PROCS <n>"
 */

int init_socket(const char *path) {
    int fd;
    struct sockaddr_un addr;

    unlink(path);

    fd = socket(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
    if (fd < 0) {
        log_error("socket: failed to create unix socket");
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, path, sizeof(addr.sun_path) - 1);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_error("socket: bind failed on %s", path);
        close(fd);
        return -1;
    }

    if (listen(fd, 8) < 0) {
        log_error("socket: listen failed");
        close(fd);
        return -1;
    }

    log_info("socket: listening on %s", path);
    return fd;
}

static void respond(int fd, const char *msg) {
    write(fd, msg,    strlen(msg));
    write(fd, "\n",   1);
}

static void handle_command(int client_fd) {
    char buf[512];
    char resp[128];
    ssize_t n;

    n = read(client_fd, buf, sizeof(buf) - 1);
    if (n <= 0)
        return;
    buf[n] = '\0';
    buf[strcspn(buf, "\r\n")] = '\0';

    if (strncmp(buf, "LAUNCH ", 7) == 0) {
        const char *path = buf + 7;
        if (*path == '\0') {
            respond(client_fd, "ERR missing path");
            return;
        }

        /* fork the process — retries are handled async in reap_children */
        pid_t pid = do_fork_exec(path, NULL, 0);
        if (pid < 0) {
            respond(client_fd, "ERR fork failed");
            return;
        }

        proc_table_add(pid, path, 0);
        log_info("socket: launched %s as pid %d", path, pid);
        snprintf(resp, sizeof(resp), "OK %d", pid);
        respond(client_fd, resp);

    } else if (strncmp(buf, "KILL ", 5) == 0) {
        pid_t pid = (pid_t)atoi(buf + 5);

        /* never allow killing PID 1 (us) or the shell */
        if (pid <= 1) {
            respond(client_fd, "ERR cannot kill pid <= 1");
            return;
        }
        if (pid == shell_pid) {
            respond(client_fd, "ERR cannot kill shell");
            return;
        }

        if (kill(pid, SIGTERM) < 0) {
            snprintf(resp, sizeof(resp), "ERR kill failed: %d", errno);
            respond(client_fd, resp);
            return;
        }

        log_info("socket: sent SIGTERM to pid %d", pid);
        respond(client_fd, "OK");

    } else if (strcmp(buf, "STATUS") == 0) {
        int active = 0;
        for (int i = 0; i < MAX_PROCS; i++)
            if (proc_table[i].active) active++;
        snprintf(resp, sizeof(resp), "SHELL %d PROCS %d", shell_pid, active);
        respond(client_fd, resp);

    } else {
        respond(client_fd, "ERR unknown command");
    }
}

void handle_socket_client(int sock_fd) {
    int client_fd = accept(sock_fd, NULL, NULL);
    if (client_fd < 0)
        return;
    handle_command(client_fd);
    close(client_fd);
}

