#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/sysinfo.h>
#include <sys/utsname.h>

/* ------------------------------------------------------------------ */
/* ANSI codes                                                           */
/* ------------------------------------------------------------------ */
#define R       "\033[0m"
#define BOLD    "\033[1m"
#define WHITE   "\033[1;37m"
#define YELLOW  "\033[1;33m"
#define CYAN    "\033[1;36m"
#define BLUE    "\033[1;34m"
#define DGRAY   "\033[90m"

/* color blocks printed on the blank line at the bottom of the logo */
#define CBLOCKS \
    "\033[40m  \033[41m  \033[42m  \033[43m  " \
    "\033[44m  \033[45m  \033[46m  \033[47m  " R

/* ------------------------------------------------------------------ */
/* Tux logo                                                             */
/*                                                                      */
/* Every line is exactly 16 visible characters.                         */
/* Trailing spaces are part of the literal to keep column alignment     */
/* stable regardless of ANSI escape lengths.                            */
/*                                                                      */
/* Visible layout (. = space):                                          */
/*   .......--.......   line 0  (6 + 4 + 6  = 16)                      */
/*   .....|o_o.|....   line 1  (5 + 6 + 5  = 16)                      */
/*   .....|:_/.|....   line 2  (5 + 6 + 5  = 16)                      */
/*   ....//...\.\.....   line 3  (4 + 8 + 4  = 16)                      */
/*   ...(|.....|.)...   line 4  (3 + 10 + 3 = 16)                      */
/*   ../'\_.._/`\...   line 5  (2 + 11 + 3 = 16)                      */
/*   ..\___)==___/...   line 6  (2 + 11 + 3 = 16)                      */
/*   ████████████████   line 7  color blocks (16 visible)               */
/* ------------------------------------------------------------------ */

#define LOGO_H 8
#define LOGO_W 16   /* visible width — used for column math */

static const char *logo[LOGO_H] = {
    /* 0 — .......--.......  (6 + ".--.": 4 + 6 = 16) */
    "      " WHITE ".--." R "      ",

    /* 1 — .....|o_o.|.....  (5 + "|o_o |": 6 + 5 = 16) */
    "     " WHITE "|" YELLOW "o" WHITE "_" YELLOW "o" WHITE " |" R "     ",

    /* 2 — .....|:_/.|.....  (5 + "|:_/ |": 6 + 5 = 16) */
    "     " WHITE "|" YELLOW ":_/" WHITE " |" R "     ",

    /* 3 — ....//...\.\.....  (4 + "//   \ \": 8 + 4 = 16) */
    "    " WHITE "//   \\ \\" R "    ",

    /* 4 — ...(|.....|.)...  (3 + "(|     | )": 10 + 3 = 16) */
    "   " WHITE "(|     | )" R "   ",

    /* 5 — ../'\_..._/`\...  (2 + "/'\_   _/`\": 11 + 3 = 16) */
    "  " WHITE "/'\\_   _/`\\" R "   ",

    /* 6 — ..\\___)=(___/...  (2 + "\___)=(___/": 11 + 3 = 16) */
    "  " WHITE "\\___)=(" YELLOW "___/" R "   ",

    /* 7 — color palette blocks, 8 x 2 spaces = 16 visible */
    CBLOCKS "        ",
};

/* ------------------------------------------------------------------ */
/* CPU brand via CPUID (x86 / x86_64 only)                            */
/* ------------------------------------------------------------------ */

#if defined(__x86_64__) || defined(__i386__)
static void get_cpu_brand(char out[49]) {
    unsigned int *p = (unsigned int *)(void *)out;
    unsigned int  leaf;
    /* leaves 0x80000002-0x80000004 give a 48-byte brand string */
    for (leaf = 0x80000002; leaf <= 0x80000004; leaf++, p += 4)
        __asm__ volatile("cpuid"
            : "=a"(p[0]), "=b"(p[1]), "=c"(p[2]), "=d"(p[3])
            : "a"(leaf));
    out[48] = '\0';
    /* trim leading spaces that some BIOSes insert */
    char *s = out;
    while (*s == ' ') s++;
    if (s != out) memmove(out, s, strlen(s) + 1);
}
#else
static void get_cpu_brand(char out[49]) {
    strncpy(out, "unknown arch", 49);
}
#endif

/* ------------------------------------------------------------------ */
/* Formatting helpers                                                   */
/* ------------------------------------------------------------------ */

static void fmt_uptime(long secs, char *buf, size_t len) {
    long d = secs / 86400;
    long h = (secs % 86400) / 3600;
    long m = (secs % 3600)  / 60;
    long s =  secs % 60;

    if      (d) snprintf(buf, len, "%ldd %ldh %ldm",   d, h, m);
    else if (h) snprintf(buf, len, "%ldh %ldm",         h, m);
    else if (m) snprintf(buf, len, "%ldm %lds",         m, s);
    else        snprintf(buf, len, "%lds",               s);
}

static void fmt_bytes(unsigned long bytes, char *buf, size_t len) {
    if      (bytes >= 1024UL * 1024 * 1024)
        snprintf(buf, len, "%.1f GB", bytes / (1024.0 * 1024 * 1024));
    else if (bytes >= 1024UL * 1024)
        snprintf(buf, len, "%.0f MB", bytes / (1024.0 * 1024));
    else
        snprintf(buf, len, "%.0f KB", bytes / 1024.0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void) {
    struct utsname uts;
    struct sysinfo si;
    char hostname[256];
    char uptime_buf[32];
    char mem_used[32], mem_total[32];
    char cpu[49];
    char separator[128];

    uname(&uts);
    sysinfo(&si);
    gethostname(hostname, sizeof(hostname) - 1);
    get_cpu_brand(cpu);

    unsigned long unit  = si.mem_unit;
    unsigned long total = si.totalram  * unit;
    unsigned long used  = (si.totalram - si.freeram) * unit;

    fmt_uptime(si.uptime, uptime_buf, sizeof(uptime_buf));
    fmt_bytes(used,  mem_used,  sizeof(mem_used));
    fmt_bytes(total, mem_total, sizeof(mem_total));

    /* separator matches visible length of "nodename@hostname" */
    {
        int len = (int)(strlen(uts.nodename) + 1 + strlen(hostname));
        if (len > 126) len = 126;
        int i;
        for (i = 0; i < len; i++) separator[i] = '-';
        separator[i] = '\0';
    }

    const char *shell = getenv("SHELL");
    if (!shell || shell[0] == '\0') shell = "/bin/sh";

    /* load averages — kernel scales by 2^16 */
    double load1  = si.loads[0] / 65536.0;
    double load5  = si.loads[1] / 65536.0;
    double load15 = si.loads[2] / 65536.0;

/* info line helpers — label always BLUE BOLD, value WHITE */
#define LABEL  BLUE BOLD
#define VAL    R WHITE
#define END    R

    /* build info lines into stack buffers */
    char i0[256], i1[256], i2[256], i3[256], i4[256];
    char i5[256], i6[256], i7[256], i8[256];

    snprintf(i0, sizeof(i0),
             CYAN BOLD "%s" END "@" CYAN BOLD "%s" END,
             uts.nodename, hostname);
    snprintf(i1, sizeof(i1), WHITE "%s" END, separator);
    snprintf(i2, sizeof(i2),
             LABEL "OS:     " VAL "Linux %s" END, uts.release);
    snprintf(i3, sizeof(i3),
             LABEL "Kernel: " VAL "%s %s" END, uts.sysname, uts.version);
    snprintf(i4, sizeof(i4),
             LABEL "Uptime: " VAL "%s" END, uptime_buf);
    snprintf(i5, sizeof(i5),
             LABEL "CPU:    " VAL "%s" END, cpu);
    snprintf(i6, sizeof(i6),
             LABEL "Memory: " VAL "%s / %s" END, mem_used, mem_total);
    snprintf(i7, sizeof(i7),
             LABEL "Load:   " VAL "%.2f  %.2f  %.2f" END
             DGRAY "  (1m 5m 15m)" END,
             load1, load5, load15);
    snprintf(i8, sizeof(i8),
             LABEL "Shell:  " VAL "%s" END
             DGRAY "   procs: %d" END,
             shell, si.procs);

    const char *info[] = { i0, i1, i2, i3, i4, i5, i6, i7, i8 };
    int info_n = (int)(sizeof(info) / sizeof(info[0]));

    int total_lines = LOGO_H > info_n ? LOGO_H : info_n;
    static const char *blank = "                ";   /* 16 spaces */

    printf("\n");
    for (int i = 0; i < total_lines; i++) {
        const char *ll = i < LOGO_H  ? logo[i]  : blank;
        const char *il = i < info_n  ? info[i]  : "";
        /* 2-space left margin, logo (16 visible), 4-space gap, info */
        printf("  %s    %s\n", ll, il);
    }
    printf("\n");

    return 0;
}

