#define SOCKET_PATH "/run/minit.sock"
#define VERSION     "1.0.0"

/* ------------------------------------------------------------------ */
/* ANSI                                                                 */
/* ------------------------------------------------------------------ */
#define R       "\033[0m"
#define BOLD    "\033[1m"
#define CYAN    "\033[1;36m"
#define GREEN   "\033[1;32m"
#define YELLOW  "\033[1;33m"
#define RED     "\033[1;31m"
#define DGRAY   "\033[90m"

/* ------------------------------------------------------------------ */
/* Socket                                                               */
/* ------------------------------------------------------------------ */

static int connect_to_minit(void) {
    int fd;
    struct sockaddr_un addr;

    fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (fd < 0) {
        fprintf(stderr, RED "error:" R " cannot create socket: %s\n", strerror(errno));
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, RED "error:" R " cannot connect to minit socket at %s\n"
                        DGRAY "       is minit running as PID 1?" R "\n",
                        SOCKET_PATH, "");
        close(fd);
        return -1;
    }

    return fd;
}

/* Send a command, read one response line, return it in buf. */
static int transact(const char *cmd, char *buf, size_t len) {
    int fd = connect_to_minit();
    if (fd < 0) return -1;

    /* send command */
    char msg[512];
    snprintf(msg, sizeof(msg), "%s\n", cmd);
    if (write(fd, msg, strlen(msg)) < 0) {
        fprintf(stderr, RED "error:" R " write failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    /* read response */
    ssize_t n = read(fd, buf, len - 1);
    close(fd);

    if (n <= 0) {
        fprintf(stderr, RED "error:" R " no response from minit\n");
        return -1;
    }

    buf[n] = '\0';
    buf[strcspn(buf, "\r\n")] = '\0';
    return 0;
}

/* ------------------------------------------------------------------ */
/* Commands                                                             */
/* ------------------------------------------------------------------ */

static void cmd_help(void) {
    printf("\n"
           CYAN BOLD "minit" R " " DGRAY "v" VERSION R "\n"
           DGRAY "Mini init process manager — userland frontend\n" R
           "\n"
           BOLD "Usage:" R "\n"
           "  minit " YELLOW "--status" R "              show running processes and shell PID\n"
           "  minit " YELLOW "--launch" R " " CYAN "<path>" R "      launch a program (retries up to 3x on failure)\n"
           "  minit " YELLOW "--kill" R "   " CYAN "<pid>" R "        send SIGTERM to a process\n"
           "  minit " YELLOW "--help" R "               show this message\n"
           "  minit " YELLOW "--version" R "            show version\n"
           "\n"
           BOLD "Socket:" R "\n"
           "  " DGRAY SOCKET_PATH R "\n"
           "\n"
           BOLD "Notes:" R "\n"
           "  " DGRAY "- The shell (PID shown in --status) cannot be killed via --kill\n"
           "  - PID 1 (minit itself) cannot be targeted\n"
           "  - Programs launched via --launch are automatically retried\n"
           "    up to 3 times on failure before being abandoned\n" R
           "\n");
}

static void cmd_version(void) {
    printf(CYAN BOLD "minit" R " v" VERSION "\n");
}

static void cmd_status(void) {
    char buf[256];
    if (transact("STATUS", buf, sizeof(buf)) < 0)
        exit(1);

    /* response: "SHELL <pid> PROCS <n>" */
    int shell_pid = 0, procs = 0;
    if (sscanf(buf, "SHELL %d PROCS %d", &shell_pid, &procs) != 2) {
        fprintf(stderr, RED "error:" R " unexpected response: %s\n", buf);
        exit(1);
    }

    printf("\n"
           CYAN BOLD "minit" R " " DGRAY "v" VERSION R "\n"
           "\n"
           "  " BOLD "Shell PID:  " R GREEN "%d" R "\n"
           "  " BOLD "Processes:  " R YELLOW "%d" R " tracked\n"
           "  " BOLD "Socket:     " R DGRAY SOCKET_PATH R "\n"
           "  " BOLD "Status:     " R GREEN "running" R "\n"
           "\n",
           shell_pid, procs);
}

static void cmd_launch(const char *path) {
    char cmd[512];
    char buf[256];

    snprintf(cmd, sizeof(cmd), "LAUNCH %s", path);
    if (transact(cmd, buf, sizeof(buf)) < 0)
        exit(1);

    /* response: "OK <pid>" or "ERR <reason>" */
    if (strncmp(buf, "OK", 2) == 0) {
        int pid = 0;
        sscanf(buf, "OK %d", &pid);
        printf(GREEN "launched" R " %s as pid " BOLD "%d" R "\n", path, pid);
    } else {
        fprintf(stderr, RED "failed:" R " %s\n", buf + (strncmp(buf, "ERR ", 4) == 0 ? 4 : 0));
        exit(1);
    }
}

static void cmd_kill(const char *pid_str) {
    char cmd[64];
    char buf[256];

    /* basic validation */
    for (const char *p = pid_str; *p; p++) {
        if (*p < '0' || *p > '9') {
            fprintf(stderr, RED "error:" R " '%s' is not a valid PID\n", pid_str);
            exit(1);
        }
    }

    snprintf(cmd, sizeof(cmd), "KILL %s", pid_str);
    if (transact(cmd, buf, sizeof(buf)) < 0)
        exit(1);

    if (strncmp(buf, "OK", 2) == 0) {
        printf(GREEN "sent SIGTERM" R " to pid " BOLD "%s" R "\n", pid_str);
    } else {
        fprintf(stderr, RED "failed:" R " %s\n", buf + (strncmp(buf, "ERR ", 4) == 0 ? 4 : 0));
        exit(1);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[]) {
    if (argc < 2) {
        cmd_help();
        return 0;
    }

    const char *flag = argv[1];

    if (strcmp(flag, "--help") == 0 || strcmp(flag, "-h") == 0) {
        cmd_help();

    } else if (strcmp(flag, "--version") == 0 || strcmp(flag, "-v") == 0) {
        cmd_version();

    } else if (strcmp(flag, "--status") == 0 || strcmp(flag, "-s") == 0) {
        cmd_status();

    } else if (strcmp(flag, "--launch") == 0 || strcmp(flag, "-l") == 0) {
        if (argc < 3) {
            fprintf(stderr, RED "error:" R " --launch requires a path\n"
                            DGRAY "       usage: minit --launch /bin/myapp\n" R);
            return 1;
        }
        cmd_launch(argv[2]);

    } else if (strcmp(flag, "--kill") == 0 || strcmp(flag, "-k") == 0) {
        if (argc < 3) {
            fprintf(stderr, RED "error:" R " --kill requires a PID\n"
                            DGRAY "       usage: minit --kill 42\n" R);
            return 1;
        }
        cmd_kill(argv[2]);

    } else {
        fprintf(stderr, RED "error:" R " unknown option '%s'\n"
                        DGRAY "       run 'minit --help' for usage\n" R, flag);
        return 1;
    }

    return 0;
}

