#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/select.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

/* ------------------------------------------------------------------ */
/* Settings                                                             */
/* ------------------------------------------------------------------ */
#define COLS     28
#define ROWS     16
#define MAX_LEN  (COLS * ROWS)
#define TICK_MS  130

/* ------------------------------------------------------------------ */
/* ANSI                                                                 */
/* ------------------------------------------------------------------ */
#define RS      "\033[0m"
#define HOME    "\033[H"
#define CLS     "\033[2J"
#define HIDE    "\033[?25l"
#define SHOW    "\033[?25h"
#define BG_GRN  "\033[42m"
#define BG_RED  "\033[41m"
#define BG_BLU  "\033[44m"
#define FG_DGRN "\033[32m"
#define FG_GRN  "\033[1;32m"
#define FG_YEL  "\033[1;33m"
#define FG_CYN  "\033[1;36m"
#define FG_RED  "\033[1;31m"
#define FG_GRY  "\033[90m"
#define BOLD    "\033[1m"

/* ------------------------------------------------------------------ */
/* Types                                                                */
/* ------------------------------------------------------------------ */
typedef enum  { D_UP, D_DOWN, D_LEFT, D_RIGHT } dir_t;
typedef struct { int x, y; }                     pos_t;

/* ------------------------------------------------------------------ */
/* State                                                                */
/* ------------------------------------------------------------------ */
static pos_t          snake[MAX_LEN];
static int            slen;
static dir_t          dir, ndir;
static pos_t          food;
static int            score, best;
static int            alive;
static struct termios saved_term;

/* ------------------------------------------------------------------ */
/* Terminal                                                             */
/* ------------------------------------------------------------------ */
static void raw_on(void) {
    struct termios t;
    tcgetattr(STDIN_FILENO, &saved_term);
    t = saved_term;
    t.c_lflag &= ~(unsigned)(ICANON | ECHO);
    t.c_cc[VMIN]  = 0;
    t.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &t);
    write(STDOUT_FILENO, HIDE CLS, strlen(HIDE CLS));
}

static void raw_off(void) {
    tcsetattr(STDIN_FILENO, TCSANOW, &saved_term);
    write(STDOUT_FILENO, SHOW RS "\n", strlen(SHOW RS "\n"));
}

static void on_signal(int s) { (void)s; raw_off(); _exit(0); }

/* ------------------------------------------------------------------ */
/* Helpers                                                              */
/* ------------------------------------------------------------------ */
static int on_snake(int x, int y, int skip_tail) {
    int n = skip_tail ? slen - 1 : slen;
    for (int i = 0; i < n; i++)
        if (snake[i].x == x && snake[i].y == y) return 1;
    return 0;
}

static void place_food(void) {
    do {
        food.x = rand() % COLS;
        food.y = rand() % ROWS;
    } while (on_snake(food.x, food.y, 0));
}

static void game_init(void) {
    slen  = 3;
    dir   = D_RIGHT;
    ndir  = D_RIGHT;
    score = 0;
    alive = 1;
    snake[0] = (pos_t){ COLS/2,     ROWS/2 };
    snake[1] = (pos_t){ COLS/2 - 1, ROWS/2 };
    snake[2] = (pos_t){ COLS/2 - 2, ROWS/2 };
    place_food();
}

/* ------------------------------------------------------------------ */
/* Input — returns 1 if quit requested                                  */
/* ------------------------------------------------------------------ */
static int read_input(void) {
    char c;
    while (read(STDIN_FILENO, &c, 1) == 1) {
        if (c == 'q' || c == 'Q') return 1;

        if (c == '\033') {
            char seq[2] = {0, 0};
            read(STDIN_FILENO, &seq[0], 1);
            read(STDIN_FILENO, &seq[1], 1);
            if (seq[0] == '[') {
                if (seq[1] == 'A' && dir != D_DOWN)  ndir = D_UP;
                if (seq[1] == 'B' && dir != D_UP)    ndir = D_DOWN;
                if (seq[1] == 'C' && dir != D_LEFT)  ndir = D_RIGHT;
                if (seq[1] == 'D' && dir != D_RIGHT) ndir = D_LEFT;
            }
            continue;
        }

        if ((c=='w'||c=='W') && dir!=D_DOWN)  ndir = D_UP;
        if ((c=='s'||c=='S') && dir!=D_UP)    ndir = D_DOWN;
        if ((c=='d'||c=='D') && dir!=D_LEFT)  ndir = D_RIGHT;
        if ((c=='a'||c=='A') && dir!=D_RIGHT) ndir = D_LEFT;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Update                                                               */
/* ------------------------------------------------------------------ */
static void game_tick(void) {
    dir = ndir;

    pos_t h = snake[0];
    if (dir == D_UP)    h.y--;
    if (dir == D_DOWN)  h.y++;
    if (dir == D_LEFT)  h.x--;
    if (dir == D_RIGHT) h.x++;

    /* wall or self collision */
    if (h.x < 0 || h.x >= COLS || h.y < 0 || h.y >= ROWS
            || on_snake(h.x, h.y, 1)) {
        alive = 0;
        return;
    }

    int ate = (h.x == food.x && h.y == food.y);

    if (ate) {
        memmove(&snake[1], &snake[0], slen * sizeof(pos_t));
        slen++;
        score++;
        if (score > best) best = score;
        place_food();
    } else {
        memmove(&snake[1], &snake[0], (slen - 1) * sizeof(pos_t));
    }
    snake[0] = h;
}

/* ------------------------------------------------------------------ */
/* Frame buffer                                                         */
/* ------------------------------------------------------------------ */
static char   fb[65536];
static size_t fp;

static void fb_s(const char *s) {
    size_t n = strlen(s);
    memcpy(fb + fp, s, n);
    fp += n;
}

static void fb_cell(int x, int y) {
    if (x == snake[0].x && y == snake[0].y)
        fb_s(BG_GRN "  " RS);
    else if (on_snake(x, y, 0))
        fb_s(FG_DGRN "\xe2\x96\x93\xe2\x96\x93" RS); /* ▓▓ UTF-8 */
    else if (x == food.x && y == food.y)
        fb_s(BG_RED "  " RS);
    else
        fb_s("  ");
}

/* ------------------------------------------------------------------ */
/* Draw                                                                 */
/* ------------------------------------------------------------------ */
static void draw_board(void) {
    char tmp[32];
    fp = 0;
    fb_s(HOME);

    /* header */
    fb_s("\n  " FG_CYN BOLD "SNAKE" RS
         "  " FG_GRY "score " FG_YEL BOLD);
    snprintf(tmp, sizeof(tmp), "%-4d", score); fb_s(tmp);
    fb_s(RS FG_GRY " best " FG_GRN BOLD);
    snprintf(tmp, sizeof(tmp), "%-4d", best);  fb_s(tmp);
    fb_s(RS FG_GRY "  wasd / \xe2\x86\x91\xe2\x86\x93\xe2\x86\x90\xe2\x86\x92"
         " arrows \xc2\xb7 q quit \xc2\xb7 r restart" RS "\n\n");
    /* ↑↓←→ · */

    /* top border */
    fb_s("  " BG_BLU);
    for (int i = 0; i < COLS * 2 + 2; i++) fb_s(" ");
    fb_s(RS "\n");

    /* playfield rows */
    for (int y = 0; y < ROWS; y++) {
        fb_s("  " BG_BLU " " RS);
        for (int x = 0; x < COLS; x++)
            fb_cell(x, y);
        fb_s(BG_BLU " " RS "\n");
    }

    /* bottom border */
    fb_s("  " BG_BLU);
    for (int i = 0; i < COLS * 2 + 2; i++) fb_s(" ");
    fb_s(RS "\n");

    write(STDOUT_FILENO, fb, fp);
}

static void draw_gameover(void) {
    draw_board();

    /* overlay box centered on the board
     * header = 4 rows (blank + title + blank + top border)
     * center row ~ 4 + ROWS/2 */
    int row = 3 + ROWS / 2;
    char buf[512];
    int  bw  = COLS * 2 + 2; /* board width in chars */

    /* build a separator line of bw chars */
    char sep[128] = {0};
    for (int i = 0; i < bw && i < 126; i++) sep[i] = ' ';

    snprintf(buf, sizeof(buf),
        "\033[%d;3H" BG_BLU "%s" RS "\n"
        "\033[%d;3H" BG_BLU "  " RS
            "  " FG_RED BOLD "GAME OVER" RS
            "   score " FG_YEL BOLD "%d" RS
            "  best " FG_GRN BOLD "%d" RS
            "  " BG_BLU "  " RS "\n"
        "\033[%d;3H" BG_BLU "  " RS FG_GRY
            "    r = restart    q = quit    " RS
            BG_BLU "  " RS "\n"
        "\033[%d;3H" BG_BLU "%s" RS "\n",
        row,     sep,
        row + 1, score, best,
        row + 2,
        row + 3, sep);

    write(STDOUT_FILENO, buf, strlen(buf));
}

/* ------------------------------------------------------------------ */
/* Wait for r or q after game over                                      */
/* ------------------------------------------------------------------ */
static int wait_restart(void) {
    char c;
    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(STDIN_FILENO, &fds);
        struct timeval tv = { 60, 0 };
        if (select(1, &fds, NULL, NULL, &tv) <= 0) return 0;
        while (read(STDIN_FILENO, &c, 1) == 1) {
            if (c == 'q' || c == 'Q') return 0;
            if (c == 'r' || c == 'R') return 1;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void) {
    signal(SIGINT,  on_signal);
    signal(SIGTERM, on_signal);
    signal(SIGPIPE, SIG_IGN);

    srand((unsigned)time(NULL));
    best = 0;
    raw_on();

    do {
        game_init();

        while (alive) {
            fd_set fds;
            FD_ZERO(&fds);
            FD_SET(STDIN_FILENO, &fds);
            struct timeval tv = { 0, TICK_MS * 1000 };
            select(1, &fds, NULL, NULL, &tv);

            if (read_input()) goto quit;
            game_tick();
            draw_board();
        }

        draw_gameover();
    } while (wait_restart());

quit:
    raw_off();
    printf("score %d   best %d\n", score, best);
    return 0;
}

