#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/reboot.h>
#include <unistd.h>

#define CYAN  "\033[1;36m"
#define RED   "\033[1;31m"
#define YEL   "\033[1;33m"
#define GRY   "\033[90m"
#define R     "\033[0m"

static void usage_shutdown(void) {
    puts(CYAN "shutdown" R " — power off or reboot TychaiOS\n"
         "\n"
         "  shutdown [now]        power off\n"
         "  shutdown -h [now]     power off (halt)\n"
         "  shutdown -p [now]     power off\n"
         "  shutdown -r [now]     reboot\n"
         "  shutdown -h           power off\n"
         "\n"
         GRY "  'now' is accepted but timing args are ignored — always immediate" R);
}

static void usage_reboot(void) {
    puts(CYAN "reboot" R " — restart TychaiOS\n"
         "\n"
         "  reboot               restart the system\n"
