#include <fcntl.h>
#include <linux/fb.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

/* ------------------------------------------------------------------ */
/* Framebuffer state                                                    */
/* ------------------------------------------------------------------ */
static int               fb_fd   = -1;
static uint8_t          *fb_mem  = NULL;
static uint32_t         *back    = NULL;   /* back buffer             */
static struct fb_var_screeninfo vinfo;
static struct fb_fix_screeninfo finfo;
static uint32_t          fb_w, fb_h, fb_stride; /* stride in pixels   */

/* ------------------------------------------------------------------ */
/* Color helpers — use vinfo offsets for portability                   */
/* ------------------------------------------------------------------ */
static inline uint32_t mkcolor(uint8_t r, uint8_t g, uint8_t b) {
    return ((uint32_t)r << vinfo.red.offset)
         | ((uint32_t)g << vinfo.green.offset)
         | ((uint32_t)b << vinfo.blue.offset);
}

/* ------------------------------------------------------------------ */
/* Game settings (derived after fb open)                               */
/* ------------------------------------------------------------------ */
#define TICK_MS   130
#define MAX_LEN   1024

static int CELL;           /* px per cell, chosen to fit screen        */
static int COLS, ROWS;     /* grid size                                 */
static int OX,  OY;        /* pixel origin of grid                     */

typedef enum  { D_UP, D_DOWN, D_LEFT, D_RIGHT } dir_t;
typedef struct { int x, y; }                     pos_t;

static pos_t  snake[MAX_LEN];
static int    slen;
static dir_t  dir, ndir;
static pos_t  food;
static int    score, best;
static int    alive;

/* ------------------------------------------------------------------ */
/* Terminal raw mode                                                    */
/* ------------------------------------------------------------------ */
static struct termios saved_term;

static void raw_on(void) {
    struct termios t;
    tcgetattr(STDIN_FILENO, &saved_term);
    t = saved_term;
    t.c_lflag &= ~(unsigned)(ICANON | ECHO);
    t.c_cc[VMIN]  = 0;
    t.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &t);
}

static void raw_off(void) {
    tcsetattr(STDIN_FILENO, TCSANOW, &saved_term);
}

/* ------------------------------------------------------------------ */
/* Framebuffer init / teardown                                         */
/* ------------------------------------------------------------------ */
static int fb_open(const char *dev) {
    fb_fd = open(dev, O_RDWR);
    if (fb_fd < 0) return -1;

    ioctl(fb_fd, FBIOGET_VSCREENINFO, &vinfo);
    ioctl(fb_fd, FBIOGET_FSCREENINFO, &finfo);

    fb_w      = vinfo.xres;
    fb_h      = vinfo.yres;
    fb_stride = finfo.line_length / 4;  /* bytes→pixels, assume 32bpp */

    size_t sz = finfo.smem_len;
    fb_mem = mmap(NULL, sz, PROT_READ | PROT_WRITE, MAP_SHARED, fb_fd, 0);
    if (fb_mem == MAP_FAILED) { fb_mem = NULL; return -1; }

    back = calloc(fb_w * fb_h, sizeof(uint32_t));
    return back ? 0 : -1;
}

static void fb_close(void) {
    if (back)   { free(back); back = NULL; }
    if (fb_mem) { munmap(fb_mem, finfo.smem_len); fb_mem = NULL; }
    if (fb_fd >= 0) { close(fb_fd); fb_fd = -1; }
}

static void fb_flip(void) {
    uint32_t *dst = (uint32_t *)fb_mem;
    for (uint32_t y = 0; y < fb_h; y++)
        memcpy(dst + y * fb_stride, back + y * fb_w, fb_w * sizeof(uint32_t));
}

/* ------------------------------------------------------------------ */
/* Drawing primitives (to back buffer)                                  */
/* ------------------------------------------------------------------ */
static void fill_rect(int x, int y, int w, int h, uint32_t col) {
    if (x < 0) { w += x; x = 0; }
    if (y < 0) { h += y; y = 0; }
    if (x + w > (int)fb_w) w = fb_w - x;
    if (y + h > (int)fb_h) h = fb_h - y;
    if (w <= 0 || h <= 0) return;
    for (int row = y; row < y + h; row++) {
        uint32_t *p = back + row * fb_w + x;
        for (int col_ = 0; col_ < w; col_++) p[col_] = col;
    }
}

static void fill_screen(uint32_t col) {
    uint32_t n = fb_w * fb_h;
    for (uint32_t i = 0; i < n; i++) back[i] = col;
}

/* ------------------------------------------------------------------ */
/* Game cell drawing                                                    */
/* ------------------------------------------------------------------ */
static uint32_t C_BG, C_BORDER, C_HEAD, C_BODY, C_FOOD, C_TEXT, C_DIM;

static void draw_cell(int gx, int gy, uint32_t col) {
    int px = OX + gx * CELL + 1;
    int py = OY + gy * CELL + 1;
    fill_rect(px, py, CELL - 2, CELL - 2, col);
}

/* Simple 5x7 bitmap font for score overlay */
static const uint8_t font5x7[10][7] = {
    {0x1C,0x22,0x26,0x2A,0x32,0x22,0x1C}, /* 0 */
    {0x08,0x18,0x08,0x08,0x08,0x08,0x1C}, /* 1 */
    {0x1C,0x22,0x02,0x04,0x08,0x10,0x3E}, /* 2 */
    {0x1C,0x22,0x02,0x0C,0x02,0x22,0x1C}, /* 3 */
    {0x04,0x0C,0x14,0x24,0x3E,0x04,0x04}, /* 4 */
    {0x3E,0x20,0x3C,0x02,0x02,0x22,0x1C}, /* 5 */
    {0x0C,0x10,0x20,0x3C,0x22,0x22,0x1C}, /* 6 */
    {0x3E,0x02,0x04,0x08,0x10,0x10,0x10}, /* 7 */
    {0x1C,0x22,0x22,0x1C,0x22,0x22,0x1C}, /* 8 */
    {0x1C,0x22,0x22,0x1E,0x02,0x04,0x18}, /* 9 */
};

static void draw_digit(int x, int y, int d, int scale, uint32_t col) {
    if (d < 0 || d > 9) return;
    for (int row = 0; row < 7; row++) {
        for (int bit = 4; bit >= 0; bit--) {
            if (font5x7[d][row] & (1 << bit))
                fill_rect(x + (4 - bit) * scale, y + row * scale, scale, scale, col);
        }
    }
}

static void draw_number(int x, int y, int n, int scale, uint32_t col) {
    char buf[16];
    int  len = snprintf(buf, sizeof(buf), "%d", n);
    for (int i = 0; i < len; i++)
        draw_digit(x + i * 6 * scale, y, buf[i] - '0', scale, col);
}

/* ------------------------------------------------------------------ */
/* Game logic                                                           */
/* ------------------------------------------------------------------ */
static int on_snake(int x, int y, int skip_tail) {
    int n = skip_tail ? slen - 1 : slen;
    for (int i = 0; i < n; i++)
        if (snake[i].x == x && snake[i].y == y) return 1;
    return 0;
}

static void place_food(void) {
    do { food.x = rand() % COLS; food.y = rand() % ROWS; }
    while (on_snake(food.x, food.y, 0));
}

static void game_init(void) {
    slen = 3; dir = D_RIGHT; ndir = D_RIGHT; score = 0; alive = 1;
    snake[0] = (pos_t){ COLS/2,     ROWS/2 };
    snake[1] = (pos_t){ COLS/2 - 1, ROWS/2 };
    snake[2] = (pos_t){ COLS/2 - 2, ROWS/2 };
    place_food();
}

static int read_input(void) {
    char c;
    while (read(STDIN_FILENO, &c, 1) == 1) {
        if (c == 'q' || c == 'Q') return 1;
        if (c == '\033') {
            char seq[2] = {0, 0};
            read(STDIN_FILENO, &seq[0], 1);
            read(STDIN_FILENO, &seq[1], 1);
            if (seq[0] == '[') {
                if (seq[1] == 'A' && dir != D_DOWN)  ndir = D_UP;
                if (seq[1] == 'B' && dir != D_UP)    ndir = D_DOWN;
                if (seq[1] == 'C' && dir != D_LEFT)  ndir = D_RIGHT;
                if (seq[1] == 'D' && dir != D_RIGHT) ndir = D_LEFT;
            }
            continue;
        }
        if ((c=='w'||c=='W') && dir!=D_DOWN)  ndir = D_UP;
        if ((c=='s'||c=='S') && dir!=D_UP)    ndir = D_DOWN;
        if ((c=='d'||c=='D') && dir!=D_LEFT)  ndir = D_RIGHT;
        if ((c=='a'||c=='A') && dir!=D_RIGHT) ndir = D_LEFT;
    }
    return 0;
}

static void game_tick(void) {
    dir = ndir;
    pos_t h = snake[0];
    if (dir == D_UP)    h.y--;
    if (dir == D_DOWN)  h.y++;
    if (dir == D_LEFT)  h.x--;
    if (dir == D_RIGHT) h.x++;
    if (h.x < 0 || h.x >= COLS || h.y < 0 || h.y >= ROWS || on_snake(h.x, h.y, 1)) {
        alive = 0; return;
    }
    int ate = (h.x == food.x && h.y == food.y);
    if (ate) {
        memmove(&snake[1], &snake[0], slen * sizeof(pos_t));
        slen++;
        score++;
        if (score > best) best = score;
        place_food();
    } else {
        memmove(&snake[1], &snake[0], (slen - 1) * sizeof(pos_t));
    }
    snake[0] = h;
}

/* ------------------------------------------------------------------ */
/* Draw full frame                                                      */
/* ------------------------------------------------------------------ */
static void draw_frame(void) {
    fill_screen(C_BG);

    /* border */
    fill_rect(OX - 2, OY - 2, COLS * CELL + 4, 2,            C_BORDER);
    fill_rect(OX - 2, OY + COLS*0 + ROWS*CELL, COLS*CELL+4, 2, C_BORDER);
    fill_rect(OX - 2, OY - 2, 2, ROWS * CELL + 4,            C_BORDER);
    fill_rect(OX + COLS * CELL, OY - 2, 2, ROWS * CELL + 4,  C_BORDER);

    /* food */
    draw_cell(food.x, food.y, C_FOOD);

    /* snake */
    for (int i = slen - 1; i > 0; i--) draw_cell(snake[i].x, snake[i].y, C_BODY);
    draw_cell(snake[0].x, snake[0].y, C_HEAD);

    /* HUD */
    int hud_y = OY - 2 - CELL - 2;
    if (hud_y < 2) hud_y = 2;
    draw_number(OX,          hud_y, score, 2, C_TEXT);
    draw_number(OX + COLS*CELL - 60, hud_y, best, 2, C_DIM);

    fb_flip();
}

static void draw_gameover(void) {
    /* darken play field */
    for (int y = 0; y < ROWS; y++)
        for (int x = 0; x < COLS; x++) {
            int px = OX + x * CELL, py = OY + y * CELL;
            for (int dy = 0; dy < CELL; dy++)
                for (int dx = 0; dx < CELL; dx++) {
                    uint32_t *p = back + (py+dy)*fb_w + (px+dx);
                    uint8_t r = (*p >> vinfo.red.offset)   & 0xFF;
                    uint8_t g = (*p >> vinfo.green.offset) & 0xFF;
                    uint8_t b = (*p >> vinfo.blue.offset)  & 0xFF;
                    *p = mkcolor(r/3, g/3, b/3);
                }
        }

    /* centered box */
    int bw = 14 * CELL, bh = 5 * CELL;
    int bx = OX + (COLS * CELL - bw) / 2;
    int by = OY + (ROWS * CELL - bh) / 2;
    fill_rect(bx, by, bw, bh, C_BORDER);
    fill_rect(bx+2, by+2, bw-4, bh-4, C_BG);

    /* score in box */
    draw_number(bx + bw/2 - 18, by + CELL,     score, 3, C_TEXT);
    draw_number(bx + bw/2 - 18, by + CELL*3,   best,  2, C_DIM);

    fb_flip();
}

static int wait_restart(void) {
    char c;
    while (1) {
        fd_set fds; FD_ZERO(&fds); FD_SET(STDIN_FILENO, &fds);
        struct timeval tv = { 60, 0 };
        if (select(1, &fds, NULL, NULL, &tv) <= 0) return 0;
        while (read(STDIN_FILENO, &c, 1) == 1) {
            if (c == 'q' || c == 'Q') return 0;
            if (c == 'r' || c == 'R') return 1;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Signal / cleanup                                                     */
/* ------------------------------------------------------------------ */
static void on_signal(int s) {
    (void)s;
    raw_off();
    /* restore blank screen */
    if (back)   fill_screen(0);
    if (fb_mem) fb_flip();
    fb_close();
    write(STDOUT_FILENO, "\033[H\033[2J\033[?25h", 15);
    _exit(0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void) {
    signal(SIGINT,  on_signal);
    signal(SIGTERM, on_signal);
    signal(SIGPIPE, SIG_IGN);

    const char *dev = "/dev/fb0";
    if (fb_open(dev) < 0) {
        fprintf(stderr, "snake-fb: cannot open %s — is framebuffer available?\n"
                        "  Try: snake (TUI version)\n", dev);
        return 1;
    }

    /* choose cell size so grid fills ~80% of screen */
    CELL = (int)(fb_h * 0.80) / 20;
    if (CELL < 8)  CELL = 8;
    if (CELL > 32) CELL = 32;

    ROWS = (int)(fb_h * 0.80) / CELL;
    COLS = (int)(fb_w * 0.80) / CELL;
    if (ROWS < 10) ROWS = 10;
    if (COLS < 10) COLS = 10;
    if (ROWS * COLS > MAX_LEN) ROWS = MAX_LEN / COLS;

    OX = ((int)fb_w - COLS * CELL) / 2;
    OY = ((int)fb_h - ROWS * CELL) / 2;

    /* palette */
    C_BG     = mkcolor(18,  18,  18);
    C_BORDER = mkcolor(60,  120, 200);
    C_HEAD   = mkcolor(80,  220, 80);
    C_BODY   = mkcolor(40,  160, 40);
    C_FOOD   = mkcolor(220, 60,  60);
    C_TEXT   = mkcolor(220, 220, 220);
    C_DIM    = mkcolor(100, 100, 100);

    srand((unsigned)time(NULL));
    best = 0;
    raw_on();
    write(STDOUT_FILENO, "\033[?25l", 6);  /* hide cursor in terminal */

    do {
        game_init();
        while (alive) {
            fd_set fds; FD_ZERO(&fds); FD_SET(STDIN_FILENO, &fds);
            struct timeval tv = { 0, TICK_MS * 1000 };
            select(1, &fds, NULL, NULL, &tv);
            if (read_input()) goto quit;
            game_tick();
            draw_frame();
        }
        draw_gameover();
    } while (wait_restart());

quit:
    raw_off();
    fill_screen(0); fb_flip();
    fb_close();
    write(STDOUT_FILENO, "\033[?25h\033[H\033[2J", 14);
    printf("score %d   best %d\n", score, best);
    return 0;
}

